/* @lc app=leetcode id=3593 lang=kotlin */ class Solution { fun minIncrease(n: Int, edges: Array<IntArray>, cost: IntArray): Int = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> LongArray(n).let { m -> order.sumOf { v -> g[v].orEmpty().filter { par[it] == v && it != 0 }.let { ch -> (ch.maxOfOrNull { m[it] } ?: 0L).let { mx -> m.set(v, mx + cost[v]).let { ch.count { m[it] < mx } } } } } } } } } }